package com.northstarbank.console.domain;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="case_documents") public class CaseDocument{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;public String customerId;public String category;public String uploader;public String originalName;public String contentType;public long sizeBytes;public String storageRef;public Instant createdAt=Instant.now();protected CaseDocument(){}public CaseDocument(String c,String cat,String u,String n,String type,long size,String ref){customerId=c;category=cat;uploader=u;originalName=n;contentType=type;sizeBytes=size;storageRef=ref;}}
